{"CommandLine":"python -c "
import requests
import json
import os
from datetime import datetime

session = requests.Session()
BASE_URL = 'http://localhost:5000/api'
results = []
bugs = []

def log(test_id, name, status, details, bug=None):
    r = {'test_id': test_id, 'name': name, 'status': status, 'details': details}
    results.append(r)
    if bug:
        bugs.append(bug)
    print(f'[{test_id}] {name}: {status} | {details}')

# ===== STEP 1: Login & CSRF =====
try:
    r = session.get(f'{BASE_URL}/auth/csrf-token')
    csrf = None
    if r.status_code == 200:
        csrf = r.json().get('csrf_token') or r.json().get('token')
    if csrf:
        session.headers.update({'X-CSRFToken': csrf, 'X-CSRF-Token': csrf})
    print(f'CSRF: {csrf}')
except Exception as e:
    print(f'CSRF error: {e}')

try:
    r = session.post(f'{BASE_URL}/auth/login', json={'email': 'a', 'password': 'a'})
    print(f'Login: {r.status_code} {r.text[:200]}')
    log('T01', 'Login', 'PASS' if r.status_code == 200 else 'FAIL', f'HTTP {r.status_code}')
    if r.status_code == 200:
        data = r.json()
        # Try to get token
        token = data.get('access_token') or data.get('token')
        if token:
            session.headers.update({'Authorization': f'Bearer {token}'})
except Exception as e:
    log('T01', 'Login', 'ERROR', str(e))

# ===== STEP 2: Dashboard BEFORE =====
try:
    r = session.get(f'{BASE_URL}/dashboard/summary')
    print(f'Dashboard BEFORE: {r.status_code} {r.text[:300]}')
    before_total = None
    if r.status_code == 200:
        data = r.json()
        before_total = data.get('total_emissions') or data.get('totalEmissions') or data.get('total')
        log('T02', 'Dashboard Summary BEFORE', 'PASS', f'total_emissions={before_total}')
    else:
        log('T02', 'Dashboard Summary BEFORE', 'FAIL', f'HTTP {r.status_code}')
except Exception as e:
    log('T02', 'Dashboard Summary BEFORE', 'ERROR', str(e))

# ===== STEP 3: POST emission =====
EMIT_ID = None
try:
    payload = {'source_type': 'Combustion', 'sub_type': 'Stationary', 'fuel_type': 'Natural Gas',
               'quantity': 9999.0, 'unit': 'MMBtu', 'facility_id': 1, 'year': 2024, 'month': 12, 'notes': 'Integrity test'}
    r = session.post(f'{BASE_URL}/emissions', json=payload)
    print(f'POST emission: {r.status_code} {r.text[:300]}')
    if r.status_code in [200, 201]:
        data = r.json()
        EMIT_ID = data.get('id') or data.get('emission_id') or (data.get('data') or {}).get('id')
        log('T03', 'POST Emission', 'PASS', f'EMIT_ID={EMIT_ID}')
    else:
        log('T03', 'POST Emission', 'FAIL', f'HTTP {r.status_code} {r.text[:100]}')
except Exception as e:
    log('T03', 'POST Emission', 'ERROR', str(e))

# ===== STEP 4: Dashboard AFTER =====
after_total = None
try:
    r = session.get(f'{BASE_URL}/dashboard/summary')
    if r.status_code == 200:
        data = r.json()
        after_total = data.get('total_emissions') or data.get('totalEmissions') or data.get('total')
        changed = (before_total is not None and after_total is not None and after_total != before_total)
        status = 'PASS' if changed else 'FAIL'
        log('T04', 'Dashboard AFTER emission added', status, f'before={before_total}, after={after_total}')
        if not changed and before_total is not None:
            bugs.append({'id': 'BUG-09-01', 'severity': 'HIGH', 'title': 'Dashboard total_emissions did not update after adding emission',
                         'endpoint': 'GET /api/dashboard/summary', 'expected': 'total changed', 'actual': f'before={before_total} after={after_total}'})
    else:
        log('T04', 'Dashboard AFTER emission added', 'FAIL', f'HTTP {r.status_code}')
except Exception as e:
    log('T04', 'Dashboard AFTER emission added', 'ERROR', str(e))

# ===== STEP 5: DELETE emission =====
if EMIT_ID:
    try:
        r = session.delete(f'{BASE_URL}/emissions/{EMIT_ID}')
        print(f'DELETE emission {EMIT_ID}: {r.status_code} {r.text[:200]}')
        log('T05', 'DELETE Emission', 'PASS' if r.status_code in [200, 204] else 'FAIL', f'HTTP {r.status_code}')
    except Exception as e:
        log('T05', 'DELETE Emission', 'ERROR', str(e))

# ===== STEP 6: Dashboard AFTER DELETE =====
try:
    r = session.get(f'{BASE_URL}/dashboard/summary')
    if r.status_code == 200:
        data = r.json()
        after_delete = data.get('total_emissions') or data.get('totalEmissions') or data.get('total')
        # Check if it returned close to before
        if before_total is not None and after_delete is not None:
            try:
                diff = abs(float(after_delete) - float(before_total))
                ok = diff < 1.0
            except:
                ok = (after_delete == before_total)
            status = 'PASS' if ok else 'FAIL'
            log('T06', 'Dashboard after DELETE - reverted', status, f'before={before_total} after_delete={after_delete}')
            if not ok:
                bugs.append({'id': 'BUG-09-02', 'severity': 'HIGH', 'title': 'Dashboard total_emissions did not revert after deleting emission',
                             'endpoint': 'GET /api/dashboard/summary', 'expected': f'~{before_total}', 'actual': str(after_delete)})
        else:
            log('T06', 'Dashboard after DELETE - reverted', 'SKIP', 'Cannot compare - missing values')
    else:
        log('T06', 'Dashboard after DELETE - reverted', 'FAIL', f'HTTP {r.status_code}')
except Exception as e:
    log('T06', 'Dashboard after DELETE - reverted', 'ERROR', str(e))

print(json.dumps({'results': results, 'bugs': bugs}, indent=2))
"
